import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"LoViF 2026 The First Challenge on Holistic Quality Assessment for 4D World Model (PhyScore)","description":"","frontmatter":{"title":"LoViF 2026 The First Challenge on Holistic Quality Assessment for 4D World Model (PhyScore)","arxiv":"2605.05187","date":"2026-05-06","authors":"Wei Luo, Yiting Lu, Xin Li, Haoran Li, Fengbin Guan, Chen Gao, Xin Jin, Yong Li, Zhibo Chen, et al.","categories":"cs.CV","topics":"物理感知视频生成, 世界模型评测, 异常时间戳定位","outline":[2,2]},"headers":[],"relativePath":"papers/2605.05187.md","filePath":"papers/2605.05187.md","lastUpdated":null}'),e={name:"papers/2605.05187.md"};function l(i,s,m,r,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="lovif-2026-the-first-challenge-on-holistic-quality-assessment-for-4d-world-model-physcore" tabindex="-1">LoViF 2026 The First Challenge on Holistic Quality Assessment for 4D World Model (PhyScore) <a class="header-anchor" href="#lovif-2026-the-first-challenge-on-holistic-quality-assessment-for-4d-world-model-physcore" aria-label="Permalink to &quot;LoViF 2026 The First Challenge on Holistic Quality Assessment for 4D World Model (PhyScore)&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2605.05187" target="_blank" rel="noreferrer">2605.05187</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-05-06</td></tr><tr><td><strong>作者</strong></td><td>Wei Luo, Yiting Lu, Xin Li, Haoran Li, Fengbin Guan, Chen Gao, Xin Jin, Yong Li, Zhibo Chen, et al.</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 1,554 段由 7 个世界生成模型产出的 2D/4D 视频组织一场竞赛，要求参赛者同时回归&quot;画质/物理真实性/条件对齐/时空一致性&quot;四维分数并<strong>定位物理违规发生的时间段</strong>，最终成绩按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathrm">IoU</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathrm">SRCC</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">PLCC</span></span></span></span></span> 计。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">标题说明</p><p>abs 页标题为 <em>LoViF 2026 The First Challenge on Holistic Quality Assessment for 4D World Model (PhyScore)</em>，HTML 全文标题多了副标题 <em>: Methods and Results</em>。frontmatter 按 abs 页写。作者列表在 abs 页被截断，此处保留组织者 9 人 + et al.，各参赛队成员见正文。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>世界模型正在从&quot;生成好看的视频&quot;走向&quot;被当作可信的未来预测器&quot;，而评测手段没有跟上。传统 VQA 关心空间保真与时序稳定；AIGC 时代加进了条件一致性（生成内容是否符合提示/输入）。但世界模型输出的评判还需要两件当前指标给不出的东西：<strong>生成的演化是否遵守物理规律</strong>，以及<strong>违规发生在什么时候</strong>。</p><p>第二点是这场竞赛真正的差异化设计。一个全局分数告诉开发者&quot;这段视频物理不对&quot;，但开发者需要知道的是第 2 秒到第 5 秒之间发生了什么。竞赛因此要求参赛者除了预测四维分数，还要输出物理异常的时间区间，用 IoU 度量定位质量。把&quot;诊断&quot;而非&quot;打分&quot;设为目标，是这个 benchmark 与 VBench、WorldScore 一类工作的分野。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>组织者把评测演进梳理成三段。第一段是传统视频质量评估（FAST-VQA、DOVER 这类），聚焦感知层面的空间保真与时序稳定，对生成内容的语义正确性无感。第二段是 AIGC 质量评估（CLIPScore、KVQ、AIGC-VQA、Q-Bench-Video），加入了条件一致性，衡量生成内容与提示词或输入条件的对齐。第三段是面向世界模型的评测（VBench、VBench-2.0、PhyGenBench、WorldScore、4DWorldBench、WorldArena），开始触及物理合理性、时序因果一致性与 3D/4D 内容质量。</p><p>不足被点得很具体：常规感知指标会漏掉细微但关键的物理违规（不可能的交互、不一致的受力），而纯全局分数在开发者需要知道&quot;何时何处&quot;违规时提供的诊断价值有限。这场竞赛的定位就是补上&quot;细粒度时间定位&quot;这一格。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>只用竞赛之前的已知条件重走：一方面，4D 生成（CamI2V、Diffusion-as-Shader、EX-4D、ReCamMaster、TrajectoryCrafter）已经积累出足够多样的模型来构造异质测试集，输入模态涵盖文本、图像、视频三种，天然可以分成 text-2D / image-to-4D / video-to-4D 三条赛道。另一方面，主观标注协议在 VQA 社区已经很成熟（ITU-T P.910 一脉），把&quot;打分&quot;扩展成&quot;打分 + 标注违规时间戳&quot;只是标注界面的改动，不是方法论跳跃。</p><p>真正需要设计的是<strong>标签可靠性</strong>。让四位标注者同时给出物理真实性分数和违规时间段，两者很可能不自洽——比如给了低分却没标出任何时间段，或标了时间段却给了高分。组织者的处理是加一道自动质控：用 Gemini 复查标注，专门找&quot;物理真实性分数与异常时间戳不一致&quot;的样本并修正，使时间定位与整体分数严格对齐。这是一个务实的、把大模型用在标注一致性维护而非打分本身的做法。</p><p>最后是排名公式。既然任务是双重的（回归 + 定位），公式必须显式加权。组织者给定位 0.2、给 SRCC 和 PLCC 各 0.4，意思是相关性仍是主体，定位是加分项。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>一个世界模型的&quot;物理错误&quot;是<strong>局部的时间事件</strong>，不是全局属性。把评测目标从&quot;给整段视频一个物理分&quot;改成&quot;指出物理在哪一段坏掉了&quot;，既逼着方法去真正跟踪时序动态（而不是从单帧外观统计里猜），又让评测结果对模型开发者直接可用。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>数据集</strong>：1,554 段生成视频，来自 7 个代表性世界生成模型（CamI2V、Diffusion-as-Shader、EX-4D、ReCamMaster、TrajectoryCrafter、HunyuanVideo 等）。三种输入模态对应三条赛道：text-2D、image-to-4D、video-to-4D。内容覆盖 26 个类别，其中物理类别显式包含<strong>动力学、光学、热力学</strong>，且每类都有高运动与低运动两种情形；其余类别扩展到体育、游戏、电影、卡通、第一人称视角，以及雨天、雾天、夜景等困难环境。</p><p><strong>标注</strong>：四位受过训练的专业标注者用网页系统，在 1–10 刻度上对四个维度打分：Video Quality、Physical Realism、Condition-Video Alignment、Spatial-Temporal Consistency。评 Physical Realism 时<strong>必须</strong>显式标出违规发生的时间范围（如 &quot;00:02-00:05&quot;）。随后用 Gemini 做自动质控，专门修正分数与时间戳不一致的样本。</p><p><strong>划分</strong>：训练 863 段（带四维分数与异常时间戳），验证 298 段（仅输入），测试 393 段（仅输入）。</p><p><strong>赛程</strong>：开发阶段开放验证服务器迭代；测试阶段发布测试集，官方排名要求提交 factsheet 与可复现的代码/可执行镜像（如 Docker）验证。</p><p><strong>一条典型参赛路径</strong>（以第二名 IHNI 的 MOSAIC 为例，它把&quot;模拟一组观察者&quot;这个想法做得最彻底）：取 VideoScore2（基于 Qwen2.5-VL-7B）与 Qwen3-VL-8B-Instruct 两个骨干，每个训 8 个 LoRA 适配器——4 个 &quot;4dim&quot; 适配器负责物理真实性/条件对齐/一致性/异常区间，4 个 &quot;VQ&quot; 适配器只负责画质，共 16 个适配器；每个适配器在 6 个温度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7224em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0.1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="minner">…</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.6</span><span class="mclose">}</span></span></span></span> 下查询，得到 96 个预测变体，模拟出一个观察者小组。融合时 PR/CA/CO 用受 ITU-T P.910 启发的一致性加权秩平均，VQ 取 VQ 专家的均值，异常区间由 4dim 共识经分组统计 + 多数投票再做仿射校准。训练只用官方 863 条，LoRA 秩取 64/128/256、学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">4</span></span></span></span></span></span></span></span></span></span></span></span> 或 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>、dropout 0.05，AdamW（weight decay 0.01）、余弦衰减、10% warmup、bf16，逐步 batch 1 + 梯度累积 16。输入设计按任务分化：4dim 分支重时间密度（训练 fps 从 [2.0, 6.0] 采样，推理 fps=4.0，max_pixels=129,600），VQ 分支重空间保真（训练 fps 从 [1.0, 3.0] 采样，推理 fps=2.0，max_pixels=360,000）。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>竞赛的核心公式是排名的复合分：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0044em;vertical-align:-0.31em;"></span><span class="mord"><span class="mord mathrm">Final_Score</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathrm">IOU</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathrm">SRCC</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.4</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">PLCC</span></span></span></span></span></span></p><p>其中 SRCC 与 PLCC 在四个维度上分别计算后取平均，IOU 由预测的异常时间区间与真值区间计算。</p><p>这个设计值得展开，因为它把两类性质完全不同的量放进了同一个线性组合。SRCC 是秩相关，只关心预测分数与主观分数的<strong>序</strong>是否一致：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">SRCC</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:2.4398em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.5038em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">n</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">n</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7401em;"><span style="top:-2.989em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord">1</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.6897em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">6</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.162em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-2.4413em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2587em;"><span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">d</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个样本在两组排序中的名次差。PLCC 是皮尔逊线性相关，关心的是<strong>幅度</strong>上的线性拟合优度。两者一起用是 VQA 社区的惯例：SRCC 保证排序正确，PLCC 保证预测值本身有意义。而 IoU 度量的是集合重叠：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">IoU</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.574em;vertical-align:-1.0185em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.5555em;"><span style="top:-2.2315em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mopen">[</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8785em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">t</span></span><span style="top:-3.1841em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8785em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">t</span></span><span style="top:-3.1841em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∪</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span><span class="mord">∣</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mopen">[</span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8785em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">t</span></span><span style="top:-3.1841em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8785em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">t</span></span><span style="top:-3.1841em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">^</span></span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∩</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mopen">[</span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">s</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">]</span><span class="mord">∣</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.0185em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>三者的取值都在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>（相关系数理论上可为负），所以直接加权求和在量纲上是自洽的。但要注意一个结构性后果：<strong>IoU 只占 0.2，且对&quot;无违规&quot;样本的处理由提交格式的 <code>None</code> 决定</strong>，这使得一个完全放弃时间定位的方法最多损失 0.2 分，而定位恰恰是这场竞赛宣称的差异化贡献。实测排行榜上第一名 SJTU_MM 的 IoU 是 0.607，最后一名 DYTH 是 0.538，五支队伍在这一项上的极差只有 0.07，说明它几乎没有区分度，名次实际由两个相关系数决定。</p><p>第三名 WDL 的多任务损失也给出了一个可参考的加权形式：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal">L</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">score</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord">0.35</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">prob</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord">0.40</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ts</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">score</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是四维分数的 Huber 损失（VideoQuality 权重 1.8，其余三维 1.0），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">prob</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 是异常存在与否的二元交叉熵，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ts</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 是时间戳回归的 Smooth L1。把&quot;有没有异常&quot;与&quot;异常在哪&quot;拆成分类 + 回归两个头，是处理&quot;多数视频没有违规&quot;这种不平衡的标准做法。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>排行榜（测试集，CodaBench）</strong>：</p><table tabindex="0"><thead><tr><th>名次</th><th>队伍</th><th>Final</th><th>VQ</th><th>PR</th><th>CA</th><th>CO</th><th>IoU</th><th>Runtime</th><th>Extra</th></tr></thead><tbody><tr><td>1</td><td>SJTU_MM</td><td>0.532</td><td>0.457</td><td>0.497</td><td>0.582</td><td>0.519</td><td>0.607</td><td>12.0</td><td>0</td></tr><tr><td>2</td><td>IHNI</td><td>0.525</td><td>0.467</td><td>0.489</td><td>0.562</td><td>0.501</td><td>0.605</td><td>15.0</td><td>0</td></tr><tr><td>3</td><td>WDL</td><td>0.486</td><td>0.429</td><td>0.447</td><td>0.517</td><td>0.457</td><td>0.580</td><td>12.0</td><td>0</td></tr><tr><td>4</td><td>zhilong</td><td>0.484</td><td>0.478</td><td>0.417</td><td>0.528</td><td>0.460</td><td>0.536</td><td>12.0</td><td>0</td></tr><tr><td>5</td><td>DYTH</td><td>0.399</td><td>0.362</td><td>0.305</td><td>0.461</td><td>0.329</td><td>0.538</td><td>60.0</td><td>0</td></tr></tbody></table><p>需要如实指出表注里的一处反常：组织者声明 &quot;For ConditionVideoAlignment (sorted ascending), Runtime, and ExtraData, lower is better&quot;，并在正文里说 DYTH 拿到了&quot;最低（最好）的 CA 值&quot;。但 CA 是与主观分的相关性度量，相关性越高应当越好；把它按升序排且称低者为优，与竞赛自己的 Final Score 公式（CA 计入 SRCC/PLCC 的平均，显然越高越好）直接冲突。这更可能是排行榜排序规则的配置错误，而非有意设计——从 Final Score 与各列的关系看，CA 高的队伍名次也高。</p><p><strong>最锋利的结论其实是绝对数值本身</strong>：冠军的复合分只有 0.532，四个维度的相关性都在 0.42–0.58 之间。也就是说，即使动用多个大型多模态模型集成、LoRA 微调、96 变体投票，自动指标与人类主观打分的相关性也只到中等水平。这与 VQA 社区在自然视频上动辄 0.85+ 的 SRCC 形成鲜明对比，说明世界模型生成视频的质量判断实质上是一个<strong>尚未被解决</strong>的问题，尤其是 Physical Realism（最高仅 0.497）明显低于 Condition-Video Alignment（最高 0.582）——判断&quot;生成内容对不对应输入&quot;比判断&quot;物理对不对&quot;容易得多。</p><p><strong>方法趋势</strong>（组织者的五点总结）：多分支架构主导，空间特征常用 ConvNeXt/Swin，时序与运动失真用 SlowFast/VideoMAE；显式引入物理感知表示或光流模块的方法在 IoU 与 PR 上更好；集成（跨架构或跨 epoch 权重融合）被顶尖队伍普遍采用，配合 EMA、rank-aware 损失、数据增强防过拟合；额外数据与预训练权重广泛使用；准确率与效率存在明显权衡——DYTH 的 runtime 是 60.0（其余为 12–15）却排名最后。</p><p><strong>各队做法差异</strong>：SJTU_MM 用 Qwen3-VL-8B、Qwen2.5-VL-7B、InternVL3-38B、UI-TARS-7B-SFT 四个 LMM 联合预测五个目标，LoRA + SFT（MS-Swift，10 epoch），并单独训一个 FAST-VQA 专攻画质维度，最后逐维选择性融合再平均；数据侧做了 8 帧/16 帧双采样、亮度调整、时序裁剪、空间裁剪、网格畸变四种增强，分辨率统一到长边 768 与 1440。WDL 用冻结的 InternVideo2（1B-224p-f4）提 768 维特征，<strong>与视频类型、生成器模型名的 one-hot 编码拼接</strong>后送进多任务 MLP 头（LayerNorm + GELU），5 折交叉验证集成，早停指标用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathrm">IoU</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">0.08</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord"><span class="mord mathrm">MAE</span></span></span></span></span>；报告的验证复合分约 0.420，特征提取约 0.39 s/视频，官方 factsheet 未给公开测试分。zhilong（西电）保持 CLIP 冻结，把逐帧 CLIP 嵌入与手工统计（亮度/对比度/饱和度/锐度、帧差能量、运动线索、元数据信号）拼起来，用随机森林、极端随机树、Ridge、直方图梯度提升组合预测，并按 text-2D/image-4D/video-4D <strong>分类型独立训练与推理</strong>，公开测试 0.484、本地交叉验证 0.4936。DYTH（澳门大学）把表示学习与回归解耦：冻结 Qwen3-VL-8B-Instruct，取关键帧与文本条件联合编码的倒数第二层隐状态作为文本条件嵌入，再用随机森林 + 梯度提升 + Ridge 的异质集成映射到五个目标；三个版本的内部消融显示 Version 2 改善了对齐但导致 Physical Realism 大幅掉到 0.1249，Version 3 换成冻结骨干 + 异质集成后跨指标更均衡，最终 0.3616 / 0.3048 / 0.4608 / 0.3293 / 0.5380，FinalScore 0.3989。</p><p>一处内部不一致需要标注：WDL 的方法描述文字写&quot;从 8 帧均匀采样中提取特征&quot;，而对应的图 6 流程标注写的是 &quot;Uniform Frame Sampling (4 frames)&quot; 且骨干为 <code>1B-224p-f4</code>（f4 通常指 4 帧配置）。两处矛盾，论文未说明，复现时应以骨干配置为准做验证。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：LoViF 2026 PhyScore 是第一场把&quot;世界模型生成视频的整体质量评估&quot;做成竞赛的尝试，数据集为 1,554 段来自 7 个 2D/4D 生成模型的视频，分 text-2D、image-to-4D、video-to-4D 三条赛道、26 个类别，物理类别显式覆盖动力学、光学、热力学。任务是双重的：回归 Video Quality、Physical Realism、Condition-Video Alignment、Spatial-Temporal Consistency 四维分数，并定位物理违规的时间区间。标签由四位受训标注者在 1–10 刻度上给出，再经 Gemini 自动质控修正&quot;分数与时间戳不一致&quot;的样本。排名按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">0.2</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">IoU</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord">0.4</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">SRCC</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0.4</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathrm">PLCC</span></span></span></span></span>，冠军 SJTU_MM 复合分 0.532，四个维度相关性仅 0.457–0.582。绝对数值偏低这一事实本身就是最重要的结论：世界模型视频的自动质量评估远未解决，其中 Physical Realism（最高 0.497）明显难于 Condition-Video Alignment（最高 0.582）。</p><p><strong>3 句话版</strong>：把&quot;物理违规发生在何时&quot;变成必答题，是这场竞赛区别于既有 benchmark 的核心设计。五支队伍的主流路线高度趋同：大型多模态模型 + LoRA 微调 + 多变体/多折集成，辅以显式的光流或物理感知模块提升定位。但所有方法与人类主观分的相关性都只到 0.42–0.58，说明这个问题的难度被严重低估。</p><p><strong>1 句话版</strong>：一场把物理违规时间定位纳入必答的世界模型评测竞赛，冠军复合分 0.532，暴露出自动物理评判目前只有中等相关性。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>四位标注者在 1–10 刻度上对 Physical Realism 的打分，构成了一个可被学习的一致目标</strong>。整场竞赛的所有成绩都以这批标注为真值，而报告<strong>完全没有给出任何标注者一致性统计</strong>——没有 SRCC/PLCC 的标注者间相关，没有 Krippendorff <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span>，没有 Fleiss <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span>，也没有说明四人是否各自独立标注全集还是分工。</p><p>这不是吹毛求疵。整场竞赛最好的 Physical Realism 相关性是 0.497，而这个上限有两种截然不同的解释：要么是方法不够强（竞赛的隐含前提），要么是标签本身的噪声天花板就在这附近（即标注者互相之间也只有约 0.5 的相关）。这两种解释对社区的指导意义完全相反——前者说&quot;继续做更强的模型&quot;，后者说&quot;先修标注协议&quot;。报告没有提供区分二者的任何数据。</p><p>有一个间接信号支持后者：组织者承认初次标注后存在&quot;物理真实性分数与异常时间戳不一致&quot;的情况，多到需要专门用 Gemini 跑一遍质控。这说明标注者在&quot;我给了几分&quot;和&quot;我认为哪里出了问题&quot;之间就已经不自洽；而更麻烦的是，修正方向是让时间戳去对齐分数（&quot;ensures that the temporal localization of physical violations strictly aligns with the corresponding holistic realism score&quot;），也就是说<strong>时间戳标签被分数标签污染了</strong>，两者不再是独立的监督信号。这直接影响 IoU 这一项的意义。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、直接检验上述假设的实验（假设能拿到官方训练集的逐标注者原始分数；若只有聚合分数，则用下述替代方案）：</p><ol><li><strong>若有逐标注者分数</strong>：在 863 条训练样本上计算四位标注者两两之间的 SRCC/PLCC，得到&quot;人类天花板&quot;。把它与排行榜上 0.457–0.582 的机器成绩对照。</li><li><strong>若只有聚合分数</strong>（更可能的情况）：训练一个最简单的基线——冻结 CLIP 逐帧特征取均值 + Ridge 回归，只预测四维分数、完全放弃时间定位（IoU 记 0）。这个基线的复合分上限是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">0.4</span><span class="mopen">(</span><span class="mord"><span class="mord mathrm">SRCC</span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">PLCC</span></span><span class="mclose">)</span></span></span></span>。</li><li>再训一个只用<strong>视频类型与生成器模型名 one-hot</strong>（即 WDL 使用的元数据）、完全不看画面像素的回归器。</li><li>对比三者。</li></ol><p>判定：如果纯元数据回归器就能拿到接近 0.4 的复合分，那么排行榜上大部分成绩来自&quot;猜是哪个生成器产的&quot;这一捷径，而非真正的质量判断；如果 CLIP + Ridge 基线就逼近 0.45，那么 LMM 集成带来的增益（0.484 → 0.532）只有几个点，与其复杂度不成比例。两种结果都会实质性改写对这场竞赛的解读。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击针对第三名 WDL 的设计，并由此波及整个 benchmark：<strong>WDL 把&quot;生成器模型名&quot;作为 one-hot 特征显式喂给了模型</strong>（&quot;these features are concatenated with one-hot encodings of video type and generator model name&quot;）。数据集只有 7 个生成模型，且不同模型的质量分布必然系统性不同。这意味着一个只需要&quot;记住 CamI2V 平均分是多少、HunyuanVideo 平均分是多少&quot;的查表器，就能拿到相当可观的相关性，而完全不需要看画面。WDL 拿到 0.486 排第三，这个成绩里有多少来自元数据、多少来自 InternVideo2 特征，报告没有拆解。</p><p>这是一个对整个 benchmark 有效性的替代解释：如果测试集的生成器分布与训练集相同（报告未说明是否做了跨生成器划分），那么&quot;预测质量分&quot;这个任务在很大程度上退化为&quot;识别生成器身份&quot;。这不是 WDL 的错——竞赛允许使用元数据，且其他队伍（zhilong 明确提到 &quot;metadata-derived signals&quot;，DYTH 用文本条件嵌入）也在不同程度上利用了同类信息。</p><p>判别实验：构造一个<strong>留一生成器</strong>的划分——在 6 个生成器的视频上训练，在第 7 个上测试，7 折轮换。如果各方法的相关性在这种设定下大幅下降（比如从 0.50 掉到 0.30 以下），说明当前排行榜衡量的很大一部分是生成器身份识别能力，而非可泛化的物理质量判断。对一个宣称要服务&quot;世界模型开发者&quot;的评测而言，这个设定才是真实使用场景：开发者拿它评的恰恰是训练集里没有的新模型。</p><p>第二个可预测的失败点已经写在数据里：五支队伍的 IoU 极差只有 0.536–0.607，而复合分极差是 0.399–0.532。异常时间定位——竞赛宣称的核心创新——在实际排名中几乎没有区分度。结合 §9 指出的&quot;时间戳标签被分数标签对齐修正过&quot;，一个不客气的解读是：IoU 这一项测的可能主要是&quot;能不能猜对这段视频有没有异常&quot;（二分类），而非&quot;能不能定位到具体时刻&quot;。验证方法很简单：在测试集上提交一个恒定输出（例如对所有视频都预测 &quot;00:00-视频末尾&quot;）的退化解，看它的 IoU 能拿到多少。如果这个平凡解能接近 0.5，IoU 这一项的诊断价值就基本不存在。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：本届竞赛把&quot;物理违规&quot;处理成一个<strong>标量分数 + 一个时间区间</strong>。这个表示丢掉了违规的类型信息——重力错了、动量不守恒了、材料形变不对了、光学折射反了，在标签里全部塌缩成&quot;物理真实性 6 分，02:00–05:00 有问题&quot;。而数据集其实已经按动力学、光学、热力学分了类别，标签空间却没有利用这个结构。结果是模型只能学&quot;哪里看起来怪&quot;，学不到&quot;哪条定律被违反了&quot;，这也解释了为什么 Physical Realism 是四维中相关性最低的一维（最高 0.497）：它试图用一个数概括本质上异质的失败模式。</p><p><strong>新 framing</strong>：把评测从&quot;回归 + 定位&quot;改成<strong>违规归因（violation attribution）</strong>——输出一个 (时间区间, 违反的物理原理, 可测量的物理量偏差) 三元组。例如&quot;02:1–02:4，自由落体加速度约为 3.2 m/s²，偏离 9.8 m/s²&quot;。这个 framing 的关键优势是它把主观标注替换成了<strong>可从视频反解的确定量</strong>：加速度、动量、光流散度、阴影方向与光源方向的夹角，都可以从像素恢复，不需要人打分，因而不受标注者一致性的限制（正面回应 §9 的脆弱假设）。</p><p><strong>可借鉴的相邻领域工具</strong>：一是物理学教学视频分析里成熟的视频测量法（tracker 类工具从视频轨迹反解运动学量）；二是可微渲染与单目 4D 重建，用来把像素轨迹提升到带尺度的三维量；三是异常检测里的&quot;归因&quot;文献，把定位从时间区间扩展到&quot;时间 × 物理量&quot;的二维定位。</p><p><strong>第一个实验</strong>：只做动力学这一个类别，且只做最容易反解的一条定律——重力加速度。从本届数据集的动力学类别里筛出含自由落体或抛体的片段，用现成的点跟踪器提取物体质心轨迹，二次拟合出表观加速度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span>，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">9.8∣/9.8</span></span></span></span> 作为一个<strong>零标注、完全确定</strong>的物理违规分数。然后比三件事：(a) 这个分数与人类 Physical Realism 主观分的相关性；(b) 它与冠军方案预测分数的相关性；(c) 它自身的重复性（应为 1.0）。如果 (a) 能达到 0.5 左右——即与花了 96 个 LMM 变体的 IHNI 在 PR 上的 0.489 相当——那就证明在有明确物理量的子类别上，确定性测量可以完全替代主观标注与大模型集成。这会为下一届竞赛给出一条清晰的路线：把可测量的物理量从主观打分中剥离出去，把主观标注的预算留给那些真正无法测量的维度。</p>',64)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
